timeout 120 npx -y playwright@latest install chromium 2>&1 | tail -3 && node -e "
const {chromium} = require('playwright');
(async () => {
  try { const b = await chromium.launch(); console.log('launch OK'); await b.close(); }
  catch (e) { console.log('launch FAIL:', e.message.split('\n')[0]); }
})();
" 2>&1 | tail -2

